class pendulo {
  constructor(xc,yc,rad) {
    this.xc = xc;
    this.yc = yc;
    this.rad = rad;
    this.direction1 = random([-1,1]);
    this.direction2 = random([-1,1]);
    this.color = generateColor(100);
    this.ang = random(0,PI);
		this.speed = createVector(random(-0.005,0.005),random(-0.005,0.005));
    this.speed1 = random(0.01,0.05);
    this.speed2 = random(0.01,0.05);
		this.speed3 = random(0.01,0.05);
    this.thick = 10;
    this.prev = null; // {x,y} anterior de la punta
    this.penWeight = random(0,100); // grosor del “lápiz”
  }

  display() {

    addBlur();

		this.xc += this.speed.x*this.xc;
		this.yc += this.speed.y*this.yc;

		if(this.xc >= width - border | this.xc <= border | this.yc >= height - border | this.yc <= border)
		{
			this.speed.x *= -1;
			this.speed.y *= -1;
		}

    if (dist(width/2,height/2,this.xc,this.yc) > this.rad) {
      this.direction *= -1;
    }

    strokeWeight(0.5);

    // ángulos acumulados de los tres giros
    let a1 = this.ang + this.direction1*frameCount*this.speed1;
    let a2 = this.direction2*frameCount*this.speed2;
    let a3 = this.direction2*frameCount*this.speed3;

		noBlur();

    const v = (ang) => createVector(this.rad, this.rad).rotate(ang);
    let tip = createVector(this.xc, this.yc);
    tip.add(v(a1));
    tip.add(v(a1 + a2));
    tip.add(v(a1 + a2 + a3)); // la punta está en (rad,rad) del último marco


		trail.drawingContext.shadowColor = 'rgba(0,0,0,0.35)';
		trail.drawingContext.shadowBlur  = 12;   // prueba 8–24
		trail.drawingContext.shadowOffsetX = 6;  // “relieve” hacia la derecha
		trail.drawingContext.shadowOffsetY = 6;  // “relieve” hacia abajo

    trail.push();
    trail.stroke(this.color);
		trail.strokeWeight(this.penWeight);
    trail.strokeCap(SQUARE);
		if (this.prev) {
			if (dist(this.prev.x,this.prev.y,tip.x,tip.y) < width/2)
			{
        trail.line(this.prev.x, this.prev.y, tip.x, tip.y);
			}
		}
    trail.pop();
    this.prev = {x: tip.x, y: tip.y};
  }
}

function drawOval(p1, p2, mySize) {
  let d = p1.dist(p2) + mySize*2;
  let a = atan2(p2.y-p1.y, p2.x-p1.x);
  let center = createVector((p1.x + p2.x)/2, (p1.y + p2.y)/2);
  noStroke();
  push();
  translate(center.x, center.y);
  rotate(a);
  if (d > 0.1) {
    rect(0, 0, d, mySize*2, 80, 80);
  }
  pop();
}


function addBlur() {
  drawingContext.shadowOffsetX = -2;
  drawingContext.shadowOffsetY = -2;
  drawingContext.shadowBlur = 10;
  drawingContext.shadowColor = 'black';
}

function noBlur() {
  drawingContext.shadowOffsetX = 0;
  drawingContext.shadowOffsetY = 0;
  drawingContext.shadowBlur = 0;
  drawingContext.shadowColor = 'transparent';
}


function generateColor(transp) {
  let myColor = color(random(colors));
	myColor.setAlpha(transp)
  return myColor;
}

function mousePressed() {
